import Link from "next/link";
import Navbar from "@/components/Navbar";
import { store } from "@/lib/db";
import { Stars, VerificationBadges } from "@/components/VerificationBadges";
import { TrustPill } from "@/components/VerificationBadges";

export const dynamic = "force-dynamic";

export default async function CariPage({
  searchParams,
}: {
  searchParams: { kategori?: string; lokasi?: string };
}) {
  const categoryRecords = await store.listCategories();
  const CATEGORIES = categoryRecords.map((c) => c.name);
  const kategori = searchParams.kategori || CATEGORIES[1] || CATEGORIES[0];
  const lokasi = searchParams.lokasi || "Kemang, Jakarta Selatan";
  const results = await store.listProfiles({ category: kategori });
  const resultUsers = Object.fromEntries(
    await Promise.all(results.map(async (p) => [p.userId, await store.getUserById(p.userId)] as const))
  );

                    return (
                        <main>
                              <Navbar />

                                    <div className="px-14 py-6 border-b border-border bg-surface">
                                            <div className="text-xs text-inkfaint mb-1.5">Beranda / Cari Jasa / {kategori}</div>
                                                    <div className="flex flex-wrap items-center justify-between gap-3">
                                                              <h1 className="font-display font-bold text-2xl">{kategori} di sekitar {lokasi}</h1>
                                                                      </div>
                                                                            </div>

                                                                                  <div className="max-w-[1400px] mx-auto flex items-start">
                                                                                          <aside className="w-[280px] shrink-0 p-6 border-r border-border bg-surface hidden lg:block">
                                                                                                    <div className="mb-7">
                                                                                                                <h4 className="text-xs uppercase tracking-wide text-inkfaint mb-3 font-semibold">Kategori</h4>
                                                                                                                            <div className="flex flex-col gap-1">
                                                                                                                                          {CATEGORIES.map((c) => (
                                                                                                                                                          <Link
                                                                                                                                                                            key={c}
                                                                                                                                                                                              href={`/cari?kategori=${encodeURIComponent(c)}&lokasi=${encodeURIComponent(lokasi)}`}
                                                                                                                                                                                                                className={`text-sm px-2.5 py-1.5 rounded-lg ${c === kategori ? "bg-accentsoft text-accentink font-semibold" : "text-inksoft"}`}
                                                                                                                                                                                                                                >
                                                                                                                                                                                                                                                  {c}
                                                                                                                                                                                                                                                                  </Link>
                                                                                                                                                                                                                                                                                ))}
                                                                                                                                                                                                                                                                                            </div>
                                                                                                                                                                                                                                                                                                      </div>
                                                                                                                                                                                                                                                                                                                <div className="mb-7">
                                                                                                                                                                                                                                                                                                                            <h4 className="text-xs uppercase tracking-wide text-inkfaint mb-3 font-semibold">Lencana verifikasi</h4>
                                                                                                                                                                                                                                                                                                                                        <label className="flex items-center gap-2 text-sm text-inksoft py-1"><input type="checkbox" defaultChecked className="accent-accent" />Identitas terverifikasi</label>
                                                                                                                                                                                                                                                                                                                                                    <label className="flex items-center gap-2 text-sm text-inksoft py-1"><input type="checkbox" defaultChecked className="accent-accent" />Alamat terverifikasi</label>
                                                                                                                                                                                                                                                                                                                                                                <label className="flex items-center gap-2 text-sm text-inksoft py-1"><input type="checkbox" className="accent-accent" />Keahlian tersertifikasi</label>
                                                                                                                                                                                                                                                                                                                                                                          </div>
                                                                                                                                                                                                                                                                                                                                                                                    <div>
                                                                                                                                                                                                                                                                                                                                                                                                <h4 className="text-xs uppercase tracking-wide text-inkfaint mb-3 font-semibold">Rating minimum</h4>
                                                                                                                                                                                                                                                                                                                                                                                                            <label className="flex items-center gap-2 text-sm text-inksoft py-1"><input type="radio" name="rating" className="accent-accent" />4,5 ★ ke atas</label>
                                                                                                                                                                                                                                                                                                                                                                                                                        <label className="flex items-center gap-2 text-sm text-inksoft py-1"><input type="radio" name="rating" defaultChecked className="accent-accent" />4,0 ★ ke atas</label>
                                                                                                                                                                                                                                                                                                                                                                                                                                  </div>
                                                                                                                                                                                                                                                                                                                                                                                                                                          </aside>
                                                                                                                                                                                                                                                                                                                                                                                                                                          
                                                                                                                                                                                                                                                                                                                                                                                                                                                  <div className="flex-1 p-6 md:p-8">
                                                                                                                                                                                                                                                                                                                                                                                                                                                            <div className="text-sm text-inksoft mb-4">
                                                                                                                                                                                                                                                                                                                                                                                                                                                                        <b className="text-ink">{results.length} mitra</b> ditemukan · diurutkan berdasarkan skor kepercayaan
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  </div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            <div className="flex flex-col gap-3.5">
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        {results.length === 0 && (
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      <div className="card p-8 text-center text-inksoft text-sm">
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      Belum ada mitra terverifikasi untuk kategori ini di lokasi Anda.
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    </div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                )}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            {results.map((p) => {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          const user = resultUsers[p.userId];
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        const isPending = p.status === "menunggu";
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      return (
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      <div key={p.id} className="card p-5 flex flex-col sm:flex-row gap-4">
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        <div className="w-16 h-16 sm:w-20 sm:h-20 rounded-2xl bg-accentsoft text-accentink flex items-center justify-center font-display font-bold text-lg shrink-0">
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            {user?.name.split(" ").map((n) => n[0]).slice(0, 2).join("")}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              </div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                <div className="flex-1 min-w-0">
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    <div className="flex items-start justify-between gap-3 flex-wrap">
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          <div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  <div className="font-bold">{user?.name}</div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          <div className="text-sm text-inksoft">{p.category} · {p.skills[0] ?? ""}</div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  <div className="text-xs text-inkfaint mt-1">{p.city}</div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        </div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              {isPending ? (
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      <span className="badge badge-neutral">Baru</span>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            ) : (
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    <TrustPill label={p.trustLabel} />
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          )}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              </div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  <div className="mt-3"><VerificationBadges badges={p.badges} /></div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      <div className="flex items-center gap-1.5 text-sm font-semibold mt-2.5">
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            <Stars rating={p.ratingAvg} /> {p.ratingAvg.toFixed(1)}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  <span className="text-inkfaint font-normal">({p.ratingCount} ulasan)</span>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      </div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        </div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          <div className="flex sm:flex-col items-end justify-between sm:justify-between gap-2 sm:w-40 shrink-0 text-right">
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              <div className="text-xs text-inkfaint">Mulai dari <b className="text-ink font-mono">Rp{p.priceFrom.toLocaleString("id-ID")}</b>/kunjungan</div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  <Link href={`/mitra/${p.id}`} className="bg-accent text-white text-sm font-semibold px-5 py-2.5 rounded-lg text-center w-full sm:w-auto">
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        Lihat Profil
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            </Link>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              </div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              </div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            );
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        })}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  </div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          </div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                </div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    </main>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      );
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      
